import os from 'node:os';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = '/tmp/bench-judge-job-RFzpWl/';

function listen(server) {
  return new Promise((res, rej) => {
    server.once('error', rej);
    server.listen(0, '127.0.0.1', () => res(server.address().port));
  });
}
function close(server) {
  return new Promise((res) => { try { server.closeAllConnections?.(); server.close(() => res()); } catch { res(); } });
}

for (const S of ['W', 'X', 'Y', 'Z']) {
  let fails = 0;
  const servers = [];
  const check = (name, got, exp) => {
    if (JSON.stringify(got) !== JSON.stringify(exp)) {
      fails++;
      console.log(`FAIL ${name} ${JSON.stringify(got)} ${JSON.stringify(exp)}`);
    }
  };
  try {
    const { createApp } = await import(ROOT + S + '/server.mjs');
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-' + S + '-'));
    const dataFile = path.join(dir, 'data.json');
    let server = createApp(dataFile);
    servers.push(server);
    let port = await listen(server);
    let base = () => `http://127.0.0.1:${port}`;

    const req = async (method, p, body, raw) => {
      const opts = { method, headers: {} };
      if (raw !== undefined) { opts.body = raw; opts.headers['content-type'] = 'application/json'; }
      else if (body !== undefined) { opts.body = JSON.stringify(body); opts.headers['content-type'] = 'application/json'; }
      const r = await fetch(base() + p, opts);
      const t = await r.text();
      let j; try { j = JSON.parse(t); } catch { j = t; }
      return { status: r.status, body: j };
    };
    const post = (p, b) => req('POST', p, b);
    const postRaw = (p, raw) => req('POST', p, undefined, raw);
    const get = (p) => req('GET', p);
    const fileState = () => {
      let c = null, m = null;
      try { c = fs.readFileSync(dataFile, 'utf8'); m = fs.statSync(dataFile).mtimeMs; } catch {}
      return { c, m };
    };

    await post('/groups', { id: 'g', name: 'G', members: ['Ann', 'Ben', 'Cara'] });
    await post('/groups', { id: 'h', name: 'H', members: ['Ann', 'Ben'] });

    // 1
    let r = await post('/groups/g/expenses', { description: 'coffee', payer: 'Ann', amount: 4.35 });
    check('1 amount', r.body?.amount, 4.35);
    // 2
    r = await post('/groups/g/expenses', { description: 'Taxi', payer: 'Ann', amount: 10 });
    check('2 shares', r.body?.shares, { Ann: 3.34, Ben: 3.33, Cara: 3.33 });
    // 3
    r = await post('/groups/zz/import', { entries: [] });
    check('3 status', r.status, 404);
    // 4
    r = await post('/groups/g/import', { foo: 1, entries: [] });
    check('4 body', r.body, { error: 'unknown field foo' });
    // 5
    r = await postRaw('/groups/g/import', '{"entries":[1],"__proto__":{}}');
    check('5 body', r.body, { error: 'unknown field __proto__' });
    // 6
    const entMsg = { error: 'entries must be an array of 1 to 50 items' };
    r = await post('/groups/g/import', { entries: [] });
    check('6 empty', r.body, entMsg);
    r = await post('/groups/g/import', { entries: Array.from({ length: 51 }, () => 1) });
    check('6 51', r.body, entMsg);
    // 7
    r = await post('/groups/g/import', { entries: [1], dry_run: null });
    check('7 dry_run', r.body, { error: 'dry_run must be true or false' });
    r = await post('/groups/g/import', { entries: [1], skip_recorded: 'yes' });
    check('7 skip_recorded', r.body, { error: 'skip_recorded must be true or false' });
    r = await post('/groups/g/import', { dry_run: 1, entries: 3 });
    check('7 entries-first', r.body, entMsg);
    // 8
    r = await postRaw('/groups/g/import', JSON.stringify({ entries: ['x'.repeat(11000)] }));
    check('8 413', r.status, 413);
    r = await postRaw('/groups/g/import', '[1]');
    check('8 400', r.status, 400);
    // 9
    const p18 = { type: 'payment', from: 'Ann', to: 'Ben', amount: 1 };
    const entries9 = [
      null, [], 5, { type: 'x' }, { type: 'expense', foo: 1 }, { type: 'payment', payer: 'Ann' },
      { type: 'expense', description: ' ', payer: 'Ann', amount: 1 },
      { type: 'expense', description: 'a', payer: 'Zed', amount: 1 },
      { type: 'expense', description: 'a', payer: 'Ann', amount: 1.005 },
      { type: 'expense', description: 'a', payer: 'Ann', amount: 1, split: null },
      { type: 'expense', description: 'a', payer: 'Ann', amount: 1, split: ['Ann', 'Ann'] },
      { type: 'payment', from: 'Zed', to: 'Ann', amount: 1 },
      { type: 'payment', from: 'Ann', to: 'Ann', amount: 1 },
      { type: 'payment', from: 'Ann', to: 'Ben', amount: 0 },
      { type: 'expense', description: ' COFFEE ', payer: 'Ann', amount: 4.35, split: ['Ben'] },
      { type: 'expense', description: 'new', payer: 'Ann', amount: 2 },
      { type: 'expense', description: 'NEW', payer: 'Ann', amount: 2 },
      { type: 'expense', description: 'new', payer: 'Ben', amount: 2 },
      p18, { ...p18 },
      { type: 'expense', description: 'coffee', payer: 'Ann', amount: 4.35 },
      { type: 'payment', from: 'Ann', to: null, amount: 1 },
      { type: 'expense', description: 'b', payer: 'Ann', amount: 1, type2: 1 },
      { type: 'payment', from: 'Ann', to: 'Ben', amount: 1, split: [] },
      { type: 'expense', description: 'c', payer: 'Ann', amount: '1' },
    ];
    const probs9 = [
      [0, 'not-an-object'], [1, 'not-an-object'], [2, 'not-an-object'], [3, 'bad-type'], [4, 'unknown-field'],
      [5, 'unknown-field'], [6, 'bad-description'], [7, 'bad-payer'], [8, 'bad-amount'], [9, 'bad-split'],
      [10, 'bad-split'], [11, 'bad-from'], [12, 'bad-to'], [13, 'bad-amount'], [14, 'already-recorded'],
      [16, 'duplicate'], [20, 'duplicate'], [21, 'bad-to'], [22, 'unknown-field'], [23, 'unknown-field'], [24, 'bad-amount'],
    ].map(([index, rule]) => ({ index, rule }));
    r = await post('/groups/g/import', { entries: entries9 });
    check('9 status', r.status, 422);
    check('9 body', r.body, { error: 'import rejected', problems: probs9 });
    // 10
    const two = { type: 'expense', description: 'coffee', payer: 'Ann', amount: 4.35 };
    r = await post('/groups/g/import', { entries: [two, two], skip_recorded: true });
    check('10 skip', r.body?.problems, [{ index: 1, rule: 'duplicate' }]);
    r = await post('/groups/g/import', { entries: [two, two] });
    check('10 noskip', r.body?.problems, [{ index: 0, rule: 'already-recorded' }, { index: 1, rule: 'duplicate' }]);
    // 11
    let before = fileState();
    r = await post('/groups/g/import', { entries: [two], skip_recorded: true });
    let bal = (await get('/groups/g/balances')).body?.balances;
    check('11 status', r.status, 201);
    check('11 body', r.body, { expenses: [], payments: [], skipped: [0], balances: bal });
    let after = fileState();
    check('11 content', after.c, before.c);
    check('11 mtime', after.m, before.m);
    before = fileState();
    r = await post('/groups/g/import', { entries: [two], skip_recorded: true, dry_run: true });
    bal = (await get('/groups/g/balances')).body?.balances;
    check('11 dry status', r.status, 200);
    check('11 dry body', r.body, { expenses: [], payments: [], skipped: [0], balances: bal });
    after = fileState();
    check('11 dry content', after.c, before.c);
    check('11 dry mtime', after.m, before.m);
    // 12
    const mix = {
      entries: [
        { type: 'expense', description: 'x1', payer: 'Ben', amount: 3 }, two,
        { type: 'payment', from: 'Ben', to: 'Ann', amount: 1 },
        { type: 'expense', description: 'x2', payer: 'Cara', amount: 0.1, split: ['Cara', 'Ann', 'Ben'] },
      ],
      skip_recorded: true,
    };
    before = fileState();
    const dry = await post('/groups/g/import', { ...mix, dry_run: true });
    check('12 dry status', dry.status, 200);
    check('12 dry content', fileState().c, before.c);
    const real = await post('/groups/g/import', mix);
    check('12 real status', real.status, 201);
    check('12 dry==real', dry.body, real.body);
    check('12 expense ids', real.body?.expenses?.map((e) => e.id), [3, 4]);
    check('12 payment ids', real.body?.payments?.map((e) => e.id), [1]);
    check('12 skipped', real.body?.skipped, [1]);
    check('12 expenses[1]', real.body?.expenses?.[1], {
      id: 4, description: 'x2', payer: 'Cara', amount: 0.1, split: ['Cara', 'Ann', 'Ben'],
      shares: { Cara: 0.04, Ann: 0.03, Ben: 0.03 },
    });
    bal = (await get('/groups/g/balances')).body?.balances;
    check('12 balances', real.body?.balances, bal);
    check('12 balance keys', Object.keys(real.body?.balances || {}), ['Ann', 'Ben', 'Cara']);
    r = await post('/groups/g/expenses', { description: 'z', payer: 'Ann', amount: 1 });
    check('12 next expense id', r.body?.id, 5);
    r = await post('/groups/g/payments', { from: 'Ann', to: 'Ben', amount: 1 });
    check('12 next payment id', r.body?.id, 2);
    // 13
    r = await post('/groups/h/import', { entries: [two] });
    check('13 status', r.status, 201);
    check('13 id', r.body?.expenses?.[0]?.id, 6);
    // 14
    await close(server);
    server = createApp(dataFile);
    servers.push(server);
    port = await listen(server);
    r = await get('/groups/g/expenses');
    const list = Array.isArray(r.body) ? r.body : (r.body?.expenses ?? r.body);
    check('14 ids', Array.isArray(list) ? list.map((e) => e.id) : list, [1, 2, 3, 4, 5]);
  } catch (e) {
    fails++;
    console.log(`FAIL exception ${JSON.stringify(String(e && e.stack || e))} null`);
  } finally {
    for (const s of servers) await close(s);
  }
  console.log(`${S} fails: ${fails}`);
}
process.exit(0);

